<?php
require_once '../conexao.php';require_once '../includes/rbac.php';require_once '../includes/flash.php';exigirCargo(['diretor']);
try{$stats=$pdo->query("SELECT COUNT(*) total, SUM(status='confirmado') confirmadas, COUNT(DISTINCT telefone) pacientes FROM agendamentos")->fetch();$serv=$pdo->query("SELECT servico,COUNT(*) total FROM agendamentos WHERE status<>'cancelado' GROUP BY servico ORDER BY total DESC")->fetchAll();$profs=$pdo->query("SELECT p.nome,COUNT(a.id) total FROM profissionais p LEFT JOIN agendamentos a ON a.profissional_id=p.id AND a.status<>'cancelado' GROUP BY p.id ORDER BY total DESC")->fetchAll();$mes=$pdo->query("SELECT DATE_FORMAT(data,'%Y-%m') mes,COUNT(*) total FROM agendamentos WHERE status<>'cancelado' GROUP BY mes ORDER BY mes DESC LIMIT 6")->fetchAll();}catch(Throwable $e){$stats=['total'=>0,'confirmadas'=>0,'pacientes'=>0];$serv=$profs=$mes=[];flash('error','Não foi possível carregar os indicadores.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diretoria | Espaço Aura</title><link rel="stylesheet" href="../css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a href="index.php" class="side-logo"><img src="../img/logo-aura-oficial.png"></a><small>DIRETORIA</small><a class="active" href="index.php">Dashboard</a><a href="usuarios.php">Usuários e acessos</a><a href="funcionarios.php">Dados dos funcionários</a><a href="relatorios.php">Consultas / planilha</a><a href="../admin/profissionais.php">Profissionais</a><a href="../admin/horarios.php">Horários</a><a href="../logout.php">Sair</a></aside><main class="dashboard"><div class="dash-head"><div><p class="eyebrow">ADMINISTRADOR TOTAL</p><h1>Visão geral</h1></div><div class="user-chip"><?=htmlspecialchars($_SESSION['usuario_nome'])?><small>Diretor</small></div></div><?php mostrarFlash();?><div class="stat-grid"><div class="stat-card"><span>Consultas</span><strong><?=$stats['total']??0?></strong></div><div class="stat-card"><span>Confirmadas</span><strong><?=$stats['confirmadas']??0?></strong></div><div class="stat-card"><span>Pacientes únicos</span><strong><?=$stats['pacientes']??0?></strong></div><div class="stat-card"><span>Serviços ativos</span><strong><?=count($serv)?></strong></div></div><div class="dash-grid"><section class="dash-card"><h2>Consultas por serviço</h2><div class="bar-list"><?php $mx=max(array_column($serv,'total')?:[1]);foreach($serv as $x):?><div><span><?=htmlspecialchars($x['servico'])?> <b><?=$x['total']?></b></span><i style="--w:<?=round($x['total']/$mx*100)?>%"></i></div><?php endforeach;?></div></section><section class="dash-card"><h2>Consultas por profissional</h2><div class="bar-list"><?php $mx=max(array_column($profs,'total')?:[1]);foreach($profs as $x):?><div><span><?=htmlspecialchars($x['nome'])?> <b><?=$x['total']?></b></span><i style="--w:<?=round($x['total']/$mx*100)?>%"></i></div><?php endforeach;?></div></section></div><section class="dash-card"><h2>Últimos meses</h2><div class="mini-chart"><?php foreach(array_reverse($mes) as $x):?><div><b style="height:<?=max(12,(int)$x['total']*8)?>px"></b><span><?=htmlspecialchars($x['mes'])?><small><?=$x['total']?></small></span></div><?php endforeach;?></div></section></main></div><script src="../js/app.js"></script></body></html>
